// One ticker drives spinner, elapsed, tps, AND the throttled stream flush —
// streaming deltas only repaint ~8x/s instead of per-token, which kills the
// layout flicker on fast generations.
useEffect(() => {
  if (!running) return;
  const started = Date.now();
  const t = setInterval(() => {
    setSpin((s) => s + 1);
    setElapsed(Math.floor((Date.now() - started) / 1000));
    setTps(meterRef.current.tps());
    setTpsTrend(meterRef.current.trend());
    const visible = visiblePrefix(streamBufRef.current);
    setStream(visible.split("\n").slice(-14).join("\n"));
  }, 120);
  return () => clearInterval(t);
}, [running]);
